 18	import com.zaxxer.hikari.HikariConfig;
 19	import com.zaxxer.hikari.HikariDataSource;
 20	import io.javalin.Javalin;
 21	import io.javalin.json.JavalinJackson;
 22	
 23	import javax.sql.DataSource;
 24	
 25	public class Application {
 26	
 27	    public static void main(String[] args) {
 28	        DataSource dataSource = createDataSource();
 29	        DatabaseInitializer.initialize(dataSource);
 30	
 31	        RoomRepository roomRepository = new RoomRepository(dataSource);
 32	        ReservationRepository reservationRepository = new ReservationRepository(dataSource);
 33	        MessageRepository messageRepository = new MessageRepository(dataSource);
 34	
 35	        RoomService roomService = new RoomService(roomRepository);
 36	        MessageService messageService = new MessageService(messageRepository, roomService);
 37	        ReservationService reservationService = new ReservationService(
 38	            reservationRepository, roomRepository, messageService
 39	        );
 40	        ReportService reportService = new ReportService(reservationService, roomService);
 41	
 42	        RoomController roomController = new RoomController(roomService);
 43	        ReservationController reservationController = new ReservationController(
 44	            reservationService, roomService, messageService
 45	        );
 46	        MessageController messageController = new MessageController(messageService);
 47	        ReportController reportController = new ReportController(reportService);
 48	
 49	        ObjectMapper objectMapper = new ObjectMapper();
 50	        objectMapper.registerModule(new JavaTimeModule());
 51	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 52	
 53	        int port = getPort();
 54	
 55	        Javalin app = Javalin.create(config -> {
 56	            config.jsonMapper(new JavalinJackson(objectMapper, false));
 57	        });
 58	
 59	        app.get("/rooms", roomController::getRooms);
 60	        app.post("/reservations", reservationController::createReservation);
 61	        app.get("/reservations/{id}", reservationController::getReservation);
 62	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 63	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 64	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 65	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 66	        app.get("/reservations/{id}/document", reservationController::getDocument);
 67	        app.get("/messages", messageController::getMessages);
 68	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 69	        app.get("/reports/revenue", reportController::getRevenueReport);
 70	
 71	        app.start(port);
 72	
 73	        System.out.println("Sistema de reservas da Pousada Maré Alta iniciado na porta " + port);
 74	    }
 75	
 76	    private static DataSource createDataSource() {
 77	        String dbUrl = System.getenv("DB_URL");
 78	        String dbUser = System.getenv("DB_USER");
 79	        String dbPassword = System.getenv("DB_PASSWORD");
 80	
 81	        if (dbUrl == null || dbUrl.isEmpty()) {
 82	            throw new RuntimeException("Variável DB_URL não configurada");
 83	        }
 84	
 85	        HikariConfig config = new HikariConfig();
 86	        config.setJdbcUrl(dbUrl);
 87	        config.setUsername(dbUser);
 88	        config.setPassword(dbPassword);
 89	        config.setMaximumPoolSize(10);
 90	
 91	        return new HikariDataSource(config);
 92	    }
 93	
 94	    private static int getPort() {
 95	        String portEnv = System.getenv("PORT");
 96	        if (portEnv != null && !portEnv.isEmpty()) {
 97	            return Integer.parseInt(portEnv);
 98	        }
 99	        return 7070;
100	    }
101	}
102	package com.pousadamarealta.infrastructure.web;
103	
104	import com.pousadamarealta.domain.model.RatePlanType;
105	import com.pousadamarealta.domain.model.Reservation;
106	import com.pousadamarealta.domain.model.Room;
107	import com.pousadamarealta.domain.service.MessageService;
108	import com.pousadamarealta.domain.service.ReservationService;
109	import com.pousadamarealta.domain.service.RoomService;
110	import io.javalin.http.Context;
111	
112	import java.time.LocalDate;
113	import java.time.format.DateTimeFormatter;
114	import java.time.format.DateTimeParseException;
115	import java.util.HashMap;
116	import java.util.Map;
117	
118	public class ReservationController {
119	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
120	
121	    private final ReservationService reservationService;
122	    private final RoomService roomService;
123	    private final MessageService messageService;
124	
125	    public ReservationController(ReservationService reservationService,
126	                                 RoomService roomService,
127	                                 MessageService messageService) {
128	        this.reservationService = reservationService;
129	        this.roomService = roomService;
130	        this.messageService = messageService;
131	    }
132	
133	    public void createReservation(Context ctx) {
134	        try {
135	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
136	
137	            String roomNumber = getRequiredString(body, "roomNumber");
138	            String guestName = getRequiredString(body, "guestName");
139	            String guestEmail = getRequiredString(body, "guestEmail");
140	            String guestCpf = getRequiredString(body, "guestCpf");
141	            LocalDate checkIn = parseDate(getRequiredString(body, "checkIn"));
142	            LocalDate checkOut = parseDate(getRequiredString(body, "checkOut"));
143	            int guests = getRequiredInt(body, "guests");
144	            RatePlanType ratePlan = RatePlanType.valueOf(getRequiredString(body, "ratePlan"));
145	            String companyCode = (String) body.get("companyCode");
146	
147	            Reservation reservation = reservationService.createReservation(
148	                roomNumber, guestName, guestEmail, guestCpf,
149	                checkIn, checkOut, guests, ratePlan, companyCode
150	            );
151	
152	            ctx.status(201).json(toReservationDto(reservation));
153	
154	        } catch (IllegalArgumentException e) {
155	            ctx.status(400).json(new ErrorResponse(
156	                ErrorCode.INVALID_REQUEST.name(),
157	                e.getMessage()
158	            ));
159	        } catch (ReservationService.RoomNotFoundException e) {
160	            ctx.status(404).json(new ErrorResponse(
161	                ErrorCode.ROOM_NOT_FOUND.name(),
162	                "Quarto não encontrado"
163	            ));
164	        } catch (ReservationService.RoomUnavailableException e) {
165	            ctx.status(409).json(new ErrorResponse(
166	                ErrorCode.ROOM_UNAVAILABLE.name(),
167	                "Quarto indisponível para as datas selecionadas"
168	            ));
169	        } catch (ReservationService.CapacityExceededException e) {
170	            ctx.status(422).json(new ErrorResponse(
171	                ErrorCode.CAPACITY_EXCEEDED.name(),
172	                "Número de hóspedes excede a capacidade do quarto"
173	            ));
174	        } catch (ReservationService.InvalidRequestException e) {
175	            ctx.status(400).json(new ErrorResponse(
176	                ErrorCode.INVALID_REQUEST.name(),
177	                e.getMessage()
178	            ));
179	        }
180	    }
181	
182	    public void getReservation(Context ctx) {
183	        try {
184	            Long id = Long.parseLong(ctx.pathParam("id"));
185	            Reservation reservation = reservationService.getReservation(id);
186	            ctx.json(toReservationDto(reservation));
187	        } catch (ReservationService.ReservationNotFoundException e) {
188	            ctx.status(404).json(new ErrorResponse(
189	                ErrorCode.RESERVATION_NOT_FOUND.name(),
190	                "Reserva não encontrada"
191	            ));
192	        }
193	    }
194	
195	    public void confirmReservation(Context ctx) {
196	        try {
197	            Long id = Long.parseLong(ctx.pathParam("id"));
198	            Reservation reservation = reservationService.confirmReservation(id);
199	            ctx.json(toReservationDto(reservation));
200	        } catch (ReservationService.ReservationNotFoundException e) {
201	            ctx.status(404).json(new ErrorResponse(
202	                ErrorCode.RESERVATION_NOT_FOUND.name(),
203	                "Reserva não encontrada"
204	            ));
205	        } catch (ReservationService.OperationNotAllowedException e) {
206	            ctx.status(409).json(new ErrorResponse(
207	                ErrorCode.OPERATION_NOT_ALLOWED.name(),
208	                "Operação não permitida para o status atual da reserva"
209	            ));
210	        }
211	    }
212	
213	    public void cancelReservation(Context ctx) {
214	        try {
215	            Long id = Long.parseLong(ctx.pathParam("id"));
216	            Reservation reservation = reservationService.cancelReservation(id);
217	            ctx.json(toReservationDto(reservation));
218	        } catch (ReservationService.ReservationNotFoundException e) {
219	            ctx.status(404).json(new ErrorResponse(
220	                ErrorCode.RESERVATION_NOT_FOUND.name(),
221	                "Reserva não encontrada"
222	            ));
223	        } catch (ReservationService.OperationNotAllowedException e) {
224	            ctx.status(409).json(new ErrorResponse(
225	                ErrorCode.OPERATION_NOT_ALLOWED.name(),
226	                "Operação não permitida para o status atual da reserva"
227	            ));
228	        }
229	    }
230	
231	    public void checkIn(Context ctx) {
232	        try {
233	            Long id = Long.parseLong(ctx.pathParam("id"));
234	            Reservation reservation = reservationService.checkIn(id);
235	            ctx.json(toReservationDto(reservation));
236	        } catch (ReservationService.ReservationNotFoundException e) {
237	            ctx.status(404).json(new ErrorResponse(
238	                ErrorCode.RESERVATION_NOT_FOUND.name(),
239	                "Reserva não encontrada"
240	            ));
241	        } catch (ReservationService.OperationNotAllowedException e) {
242	            ctx.status(409).json(new ErrorResponse(
243	                ErrorCode.OPERATION_NOT_ALLOWED.name(),
244	                "Operação não permitida para o status atual da reserva"
245	            ));
246	        }
247	    }
248	
249	    public void checkOut(Context ctx) {
250	        try {
251	            Long id = Long.parseLong(ctx.pathParam("id"));
252	            Reservation reservation = reservationService.checkOut(id);
253	            ctx.json(toDocumentDto(reservation));
254	        } catch (ReservationService.ReservationNotFoundException e) {
255	            ctx.status(404).json(new ErrorResponse(
256	                ErrorCode.RESERVATION_NOT_FOUND.name(),
257	                "Reserva não encontrada"
258	            ));
259	        } catch (ReservationService.OperationNotAllowedException e) {
260	            ctx.status(409).json(new ErrorResponse(
261	                ErrorCode.OPERATION_NOT_ALLOWED.name(),
262	                "Operação não permitida para o status atual da reserva"
263	            ));
264	        }
265	    }
266	
267	    public void getDocument(Context ctx) {
268	        try {
269	            Long id = Long.parseLong(ctx.pathParam("id"));
270	            Reservation reservation = reservationService.getReservation(id);
271	
272	            if (!reservation.isPaid()) {
273	                ctx.status(409).json(new ErrorResponse(
274	                    ErrorCode.OPERATION_NOT_ALLOWED.name(),
275	                    "Documento disponível apenas para reservas pagas"
276	                ));
277	                return;
278	            }
279	
280	            ctx.json(toDocumentDto(reservation));
281	        } catch (ReservationService.ReservationNotFoundException e) {
282	            ctx.status(404).json(new ErrorResponse(
283	                ErrorCode.RESERVATION_NOT_FOUND.name(),
284	                "Reserva não encontrada"
285	            ));
286	        }
287	    }
288	
289	    private Map<String, Object> toReservationDto(Reservation reservation) {
290	        Map<String, Object> dto = new HashMap<>();
291	        dto.put("id", reservation.getId());
292	        dto.put("roomNumber", reservation.getRoomNumber());
293	        dto.put("guestName", reservation.getGuestName());
294	        dto.put("guestEmail", reservation.getGuestEmail());
295	        dto.put("guestCpf", reservation.getGuestCpf());
296	        dto.put("checkIn", reservation.getCheckIn().format(DATE_FORMATTER));
297	        dto.put("checkOut", reservation.getCheckOut().format(DATE_FORMATTER));
298	        dto.put("guests", reservation.getGuests());
299	        dto.put("ratePlan", reservation.getRatePlan().name());
300	        dto.put("nights", reservation.getNights());
301	        dto.put("subtotal", reservation.getSubtotal());
302	        dto.put("discount", reservation.getDiscount());
303	        dto.put("total", reservation.getTotal());
304	        dto.put("status", reservation.getStatus().name());
305	        dto.put("amountPaid", reservation.getAmountPaid());
306	        dto.put("refund", reservation.getRefund());
307	        return dto;
308	    }
309	
310	    private Map<String, Object> toDocumentDto(Reservation reservation) {
311	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
312	
313	        Map<String, Object> dto = new HashMap<>();
314	        dto.put("title", "Comprovante de reserva");
315	        dto.put("reservationId", reservation.getId());
316	        dto.put("guestName", reservation.getGuestName());
317	        dto.put("guestCpf", reservation.getGuestCpf());
318	        dto.put("roomNumber", reservation.getRoomNumber());
319	        dto.put("roomType", room.getType().name());
320	        dto.put("checkIn", reservation.getCheckIn().format(DATE_FORMATTER));
321	        dto.put("checkOut", reservation.getCheckOut().format(DATE_FORMATTER));
322	        dto.put("nights", reservation.getNights());
323	        dto.put("subtotal", reservation.getSubtotal());
324	        dto.put("discount", reservation.getDiscount());
325	        dto.put("total", reservation.getTotal());
326	        return dto;
327	    }
328	
329	    private String getRequiredString(Map<String, Object> map, String key) {
330	        Object value = map.get(key);
331	        if (value == null) {
332	            throw new IllegalArgumentException("Campo obrigatório ausente: " + key);
333	        }
334	        return value.toString();
335	    }
336	
337	    private int getRequiredInt(Map<String, Object> map, String key) {
338	        Object value = map.get(key);
339	        if (value == null) {
340	            throw new IllegalArgumentException("Campo obrigatório ausente: " + key);
341	        }
342	        if (value instanceof Number number) {
343	            return number.intValue();
344	        }
345	        try {
346	            return Integer.parseInt(value.toString());
347	        } catch (NumberFormatException e) {
348	            throw new IllegalArgumentException("Valor inválido para " + key);
349	        }
350	    }
351	
352	    private LocalDate parseDate(String dateStr) {
353	        try {
354	            return LocalDate.parse(dateStr, DATE_FORMATTER);
355	        } catch (DateTimeParseException e) {
356	            throw new IllegalArgumentException("Formato de data inválido. Use yyyy-MM-dd");
357	        }
358	    }
359	}

