  9	
 10	import java.math.BigDecimal;
 11	import java.time.LocalDate;
 12	import java.util.List;
 13	
 14	public class ReservationService {
 15	    private final ReservationRepository reservationRepository;
 16	    private final RoomRepository roomRepository;
 17	    private final MessageService messageService;
 18	
 19	    public ReservationService(ReservationRepository reservationRepository,
 20	                             RoomRepository roomRepository,
 21	                             MessageService messageService) {
 22	        this.reservationRepository = reservationRepository;
 23	        this.roomRepository = roomRepository;
 24	        this.messageService = messageService;
 25	    }
 26	
 27	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
 28	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
 29	                                        int guests, RatePlanType ratePlanType, String companyCode) {
 30	        Room room = roomRepository.findByNumber(roomNumber)
 31	            .orElseThrow(() -> new RoomNotFoundException());
 32	
 33	        if (guests < 1) {
 34	            throw new InvalidRequestException("Número de hóspedes deve ser no mínimo 1");
 35	        }
 36	
 37	        if (guests > room.getCapacity()) {
 38	            throw new CapacityExceededException();
 39	        }
 40	
 41	        if (!checkOut.isAfter(checkIn)) {
 42	            throw new InvalidRequestException("Data de saída deve ser posterior à data de entrada");
 43	        }
 44	
 45	        RatePlan ratePlan = RatePlanRegistry.get(ratePlanType);
 46	
 47	        try {
 48	            ratePlan.validate(checkIn, checkOut, companyCode);
 49	        } catch (IllegalArgumentException e) {
 50	            throw new InvalidRequestException(e.getMessage());
 51	        }
 52	
 53	        if (isRoomUnavailable(roomNumber, checkIn, checkOut, null)) {
 54	            throw new RoomUnavailableException();
 55	        }
 56	
 57	        BigDecimal subtotal = ratePlan.calculateSubtotal(room.getType(), checkIn, checkOut);
 58	        BigDecimal discount;
 59	
 60	        if (ratePlanType == RatePlanType.CORPORATE && ratePlan instanceof CorporateRatePlan corporatePlan) {
 61	            discount = corporatePlan.calculateDiscount(subtotal, companyCode);
 62	        } else {
 63	            discount = ratePlan.calculateDiscount(subtotal, room.getType(), checkIn, checkOut);
 64	        }
 65	
 66	        BigDecimal total = subtotal.subtract(discount);
 67	
 68	        Reservation reservation = new Reservation(
 69	            roomNumber, guestName, guestEmail, guestCpf,
 70	            checkIn, checkOut, guests, ratePlanType, companyCode,
 71	            subtotal, discount, total
 72	        );
 73	
 74	        return reservationRepository.save(reservation);
 75	    }
 76	
 77	    public Reservation getReservation(Long id) {
 78	        return reservationRepository.findById(id)
 79	            .orElseThrow(() -> new ReservationNotFoundException());
 80	    }
 81	
 82	    public Reservation confirmReservation(Long id) {
 83	        Reservation reservation = getReservation(id);
 84	
 85	        try {
 86	            reservation.confirm();
 87	        } catch (IllegalStateException e) {
 88	            throw new OperationNotAllowedException();
 89	        }
 90	
 91	        Reservation saved = reservationRepository.update(reservation);
 92	        messageService.sendConfirmationEmail(saved);
 93	
 94	        return saved;
 95	    }
 96	
 97	    public Reservation cancelReservation(Long id) {
 98	        Reservation reservation = getReservation(id);
 99	
100	        try {
101	            RatePlan ratePlan = RatePlanRegistry.get(reservation.getRatePlan());
102	            BigDecimal refundAmount = ratePlan.calculateRefund(reservation.getAmountPaid());
103	            reservation.cancel(refundAmount);
104	        } catch (IllegalStateException e) {
105	            throw new OperationNotAllowedException();
106	        }
107	
108	        return reservationRepository.update(reservation);
109	    }
110	
111	    public Reservation checkIn(Long id) {
112	        Reservation reservation = getReservation(id);
113	
114	        try {
115	            reservation.checkIn();
116	        } catch (IllegalStateException e) {
117	            throw new OperationNotAllowedException();
118	        }
119	
120	        return reservationRepository.update(reservation);
121	    }
122	
123	    public Reservation checkOut(Long id) {
124	        Reservation reservation = getReservation(id);
125	
126	        try {
127	            reservation.checkOut();
128	        } catch (IllegalStateException e) {
129	            throw new OperationNotAllowedException();
130	        }
131	
132	        return reservationRepository.update(reservation);
133	    }
134	
135	    public List<Reservation> findReservationsForNight(LocalDate night) {
136	        return reservationRepository.findPaidReservationsForNight(night);
137	    }
138	
139	    public List<Reservation> findReservationsForMonth(int year, int month) {
140	        return reservationRepository.findReservationsStartingInMonth(year, month);
141	    }
142	
143	    private boolean isRoomUnavailable(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeReservationId) {
144	        List<Reservation> existingReservations = reservationRepository.findActiveReservationsByRoom(roomNumber);
145	
146	        return existingReservations.stream()
147	            .filter(r -> excludeReservationId == null || !r.getId().equals(excludeReservationId))
148	            .anyMatch(r -> datesOverlap(checkIn, checkOut, r.getCheckIn(), r.getCheckOut()));
149	    }
150	
151	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
152	        return start1.isBefore(end2) && start2.isBefore(end1);
153	    }
154	
155	    public static class RoomNotFoundException extends RuntimeException {}
156	    public static class ReservationNotFoundException extends RuntimeException {}
157	    public static class RoomUnavailableException extends RuntimeException {}
158	    public static class CapacityExceededException extends RuntimeException {}
159	    public static class OperationNotAllowedException extends RuntimeException {}
160	    public static class InvalidRequestException extends RuntimeException {
161	        public InvalidRequestException(String message) {
162	            super(message);
163	        }
164	    }
165	}
