213	        if (status != ReservationStatus.PENDING) {
214	            throw new IllegalStateException("Só é possível confirmar uma reserva pendente");
215	        }
216	        this.status = ReservationStatus.CONFIRMED;
217	        this.amountPaid = this.total;
218	    }
