220	    public void checkIn() {
221	        if (status != ReservationStatus.CONFIRMED) {
222	            throw new IllegalStateException("Só é possível fazer check-in de uma reserva confirmada");
223	        }
224	        this.status = ReservationStatus.CHECKED_IN;
225	    }
226	
227	    public void checkOut() {
228	        if (status != ReservationStatus.CHECKED_IN) {
229	            throw new IllegalStateException("Só é possível fazer check-out de uma reserva com check-in feito");
230	        }
231	        this.status = ReservationStatus.CHECKED_OUT;
232	    }
233	
234	    public void cancel(BigDecimal refundAmount) {
235	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
236	            throw new IllegalStateException("Só é possível cancelar uma reserva pendente ou confirmada");
237	        }
238	        this.status = ReservationStatus.CANCELLED;
239	        this.refund = refundAmount;
240	    }
