275	        return guests;
276	    }
277	
278	    public RatePlanType getRatePlan() {
279	        return ratePlan;
280	    }
281	
282	    public String getCompanyCode() {
283	        return companyCode;
284	    }
285	
286	    public int getNights() {
287	        return nights;
288	    }
289	
290	    public BigDecimal getSubtotal() {
291	        return subtotal;
292	    }
293	
294	    public BigDecimal getDiscount() {
295	        return discount;
296	    }
297	
298	    public BigDecimal getTotal() {
299	        return total;
300	    }
301	
302	    public ReservationStatus getStatus() {
303	        return status;
304	    }
305	
306	    public BigDecimal getAmountPaid() {
307	        return amountPaid;
308	    }
309	
310	    public BigDecimal getRefund() {
311	        return refund;
312	    }
313	
314	    public boolean isPaid() {
315	        return status == ReservationStatus.CONFIRMED ||
316	               status == ReservationStatus.CHECKED_IN ||
317	               status == ReservationStatus.CHECKED_OUT;
318	    }
319	
320	    public boolean isActive() {
321	        return status != ReservationStatus.CANCELLED;
322	    }
323	}

