     1	package com.pousadamarealta.domain.service.rateplan;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	
     7	public class SeasonCalculator {
     8	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
     9	
    10	    public static boolean isHighSeason(LocalDate date) {
    11	        int month = date.getMonthValue();
    12	        int day = date.getDayOfMonth();
    13	
    14	        if (month == 12 && day >= 15) return true;
    15	        if (month == 1 || month == 2) return true;
    16	        if (month == 7) return true;
    17	
    18	        return false;
    19	    }
    20	
    21	    public static BigDecimal applyHighSeasonIfNeeded(BigDecimal rate, LocalDate date) {
    22	        if (isHighSeason(date)) {
    23	            return roundHalfToEven(rate.multiply(HIGH_SEASON_MULTIPLIER));
    24	        }
    25	        return rate;
    26	    }
    27	
    28	    public static BigDecimal roundHalfToEven(BigDecimal value) {
    29	        return value.setScale(2, RoundingMode.HALF_EVEN);
    30	    }
    31	}
