    12	public class ReportService {
    13	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    14	
    15	    private final ReservationService reservationService;
    16	    private final RoomService roomService;
