    22	
    23	    public String generateOccupancyReport(LocalDate date) {
    24	        List<Reservation> reservations = reservationService.findReservationsForNight(date);
    25	        reservations.sort(Comparator.comparing(Reservation::getRoomNumber));
    26	
    27	        StringBuilder csv = new StringBuilder();
    28	        csv.append("room,type,reservation,check_in,check_out\n");
    29	
    30	        for (Reservation reservation : reservations) {
    31	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
    32	            csv.append(reservation.getRoomNumber()).append(",");
    33	            csv.append(room.getType()).append(",");
    34	            csv.append(reservation.getId()).append(",");
    35	            csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
    36	            csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append("\n");
    37	        }
    38	
    39	        int totalRooms = roomService.getAllRooms().size();
    40	        csv.append("total,").append(reservations.size()).append("/").append(totalRooms);
    41	
    42	        return csv.toString();
    43	    }
    44	
    45	    public String generateRevenueReport(int year, int month) {
    46	        List<Reservation> reservations = reservationService.findReservationsForMonth(year, month);
    47	
    48	        reservations.sort(Comparator
    49	            .comparing(Reservation::getCheckIn)
    50	            .thenComparing(Reservation::getId));
    51	
    52	        StringBuilder csv = new StringBuilder();
    53	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    54	
    55	        BigDecimal totalRevenue = BigDecimal.ZERO;
    56	
    57	        for (Reservation reservation : reservations) {
    58	            BigDecimal netAmount = reservation.getAmountPaid();
    59	            if (reservation.getRefund() != null) {
    60	                netAmount = netAmount.subtract(reservation.getRefund());
    61	            }
    62	
    63	            if (netAmount.compareTo(BigDecimal.ZERO) > 0) {
    64	                csv.append(reservation.getId()).append(",");
    65	                csv.append(reservation.getRoomNumber()).append(",");
    66	                csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
    67	                csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append(",");
    68	                csv.append(reservation.getStatus()).append(",");
    69	                csv.append(formatAmount(netAmount)).append("\n");
    70	
    71	                totalRevenue = totalRevenue.add(netAmount);
    72	            }
    73	        }
    74	
    75	        csv.append("total,").append(formatAmount(totalRevenue));
    76	
    77	        return csv.toString();
    78	    }
    79	
    80	    private String formatAmount(BigDecimal amount) {
    81	        return amount.toString();
    82	    }
    83	}
