    23	    public String generateOccupancyReport(LocalDate date) {
    24	        List<Reservation> reservations = reservationService.findReservationsForNight(date);
    25	        reservations.sort(Comparator.comparing(Reservation::getRoomNumber));
    26	
    27	        StringBuilder csv = new StringBuilder();
