    29	
    30	        for (Reservation reservation : reservations) {
    31	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
    32	            csv.append(reservation.getRoomNumber()).append(",");
    33	            csv.append(room.getType()).append(",");
