    47	
    48	        reservations.sort(Comparator
    49	            .comparing(Reservation::getCheckIn)
    50	            .thenComparing(Reservation::getId));
    51	
    52	        StringBuilder csv = new StringBuilder();
    53	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    54	
    55	        BigDecimal totalRevenue = BigDecimal.ZERO;
    56	
    57	        for (Reservation reservation : reservations) {
    58	            BigDecimal netAmount = reservation.getAmountPaid();
    59	            if (reservation.getRefund() != null) {
    60	                netAmount = netAmount.subtract(reservation.getRefund());
    61	            }
    62	
    63	            if (netAmount.compareTo(BigDecimal.ZERO) > 0) {
    64	                csv.append(reservation.getId()).append(",");
    65	                csv.append(reservation.getRoomNumber()).append(",");
    66	                csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
    67	                csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append(",");
    68	                csv.append(reservation.getStatus()).append(",");
    69	                csv.append(formatAmount(netAmount)).append("\n");
    70	
    71	                totalRevenue = totalRevenue.add(netAmount);
    72	            }
    73	        }
    74	
    75	        csv.append("total,").append(formatAmount(totalRevenue));
    76	
    77	        return csv.toString();
    78	    }
