 89	public class ReservationRepository {
 90	    private final DataSource dataSource;
 91	
 92	    public ReservationRepository(DataSource dataSource) {
 93	        this.dataSource = dataSource;
 94	    }
 95	
 96	    public Reservation save(Reservation reservation) {
 97	        String sql = """
 98	            INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf,
 99	                check_in, check_out, guests, rate_plan, company_code, nights, subtotal,
100	                discount, total, status, amount_paid, refund)
101	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
102	        """;
103	
104	        try (Connection conn = dataSource.getConnection();
105	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
106	
107	            setReservationParameters(stmt, reservation);
108	
109	            stmt.executeUpdate();
110	
111	            try (ResultSet rs = stmt.getGeneratedKeys()) {
112	                if (rs.next()) {
113	                    reservation.setId(rs.getLong(1));
114	                }
115	            }
116	
117	            return reservation;
118	        } catch (Exception e) {
119	            throw new RuntimeException("Erro ao salvar reserva", e);
120	        }
121	    }
122	
123	    public Reservation update(Reservation reservation) {
124	        String sql = """
125	            UPDATE reservations SET status = ?, amount_paid = ?, refund = ?
126	            WHERE id = ?
127	        """;
128	
129	        try (Connection conn = dataSource.getConnection();
130	             PreparedStatement stmt = conn.prepareStatement(sql)) {
131	
132	            stmt.setString(1, reservation.getStatus().name());
133	            stmt.setBigDecimal(2, reservation.getAmountPaid());
134	
135	            if (reservation.getRefund() != null) {
136	                stmt.setBigDecimal(3, reservation.getRefund());
137	            } else {
138	                stmt.setNull(3, Types.DECIMAL);
139	            }
140	
141	            stmt.setLong(4, reservation.getId());
