209	    public List<Reservation> findReservationsStartingInMonth(int year, int month) {
210	        String sql = """
211	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
212	                guests, rate_plan, company_code, nights, subtotal, discount, total,
213	                status, amount_paid, refund
214	            FROM reservations
215	            WHERE EXTRACT(YEAR FROM check_in) = ? AND EXTRACT(MONTH FROM check_in) = ?
216	        """;
217	
218	        try (Connection conn = dataSource.getConnection();
219	             PreparedStatement stmt = conn.prepareStatement(sql)) {
