230	    private List<Reservation> executeQuery(String sql, Object... params) {
231	        try (Connection conn = dataSource.getConnection();
232	             PreparedStatement stmt = conn.prepareStatement(sql)) {
233	
234	            for (int i = 0; i < params.length; i++) {
235	                stmt.setObject(i + 1, params[i]);
236	            }
237	
238	            return executeQuery(stmt);
239	        } catch (Exception e) {
240	            throw new RuntimeException("Erro ao executar query", e);
241	        }
242	    }
243	
244	    private List<Reservation> executeQuery(PreparedStatement stmt) throws Exception {
245	        List<Reservation> reservations = new ArrayList<>();
246	
247	        try (ResultSet rs = stmt.executeQuery()) {
248	            while (rs.next()) {
249	                reservations.add(mapReservation(rs));
250	            }
251	        }
252	
253	        return reservations;
254	    }
255	
256	    private void setReservationParameters(PreparedStatement stmt, Reservation reservation) throws Exception {
257	        stmt.setString(1, reservation.getRoomNumber());
258	        stmt.setString(2, reservation.getGuestName());
259	        stmt.setString(3, reservation.getGuestEmail());
260	        stmt.setString(4, reservation.getGuestCpf());
261	        stmt.setDate(5, Date.valueOf(reservation.getCheckIn()));
262	        stmt.setDate(6, Date.valueOf(reservation.getCheckOut()));
263	        stmt.setInt(7, reservation.getGuests());
264	        stmt.setString(8, reservation.getRatePlan().name());
265	        stmt.setString(9, reservation.getCompanyCode());
266	        stmt.setInt(10, reservation.getNights());
267	        stmt.setBigDecimal(11, reservation.getSubtotal());
268	        stmt.setBigDecimal(12, reservation.getDiscount());
269	        stmt.setBigDecimal(13, reservation.getTotal());
270	        stmt.setString(14, reservation.getStatus().name());
271	        stmt.setBigDecimal(15, reservation.getAmountPaid());
272	
273	        if (reservation.getRefund() != null) {
274	            stmt.setBigDecimal(16, reservation.getRefund());
275	        } else {
276	            stmt.setNull(16, Types.DECIMAL);
277	        }
278	    }
279	
