 10	
 11	class RatePlanTest {
 12	
 13	    @Test
 14	    void testStandardRatePlan() {
 15	        StandardRatePlan plan = new StandardRatePlan();
 16	
 17	        LocalDate checkIn = LocalDate.of(2027, 3, 10);
 18	        LocalDate checkOut = LocalDate.of(2027, 3, 12);
 19	
 20	        BigDecimal subtotal = plan.calculateSubtotal(RoomType.DELUXE, checkIn, checkOut);
 21	        BigDecimal discount = plan.calculateDiscount(subtotal, RoomType.DELUXE, checkIn, checkOut);
 22	
 23	        assertEquals(new BigDecimal("779.80"), subtotal);
 24	        assertEquals(BigDecimal.ZERO, discount);
 25	        assertEquals(new BigDecimal("779.80"), plan.calculateRefund(new BigDecimal("779.80")));
 26	    }
