 30	        NonRefundableRatePlan plan = new NonRefundableRatePlan();
 31	
 32	        LocalDate checkIn = LocalDate.of(2027, 3, 10);
 33	        LocalDate checkOut = LocalDate.of(2027, 3, 12);
